package com.ynxweb4.shop;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.concurrent.atomic.AtomicInteger;
public final class OfflineDraftRetryTest {
 private static final String PATH=BuyerTransitionRecoveryTest.path;
 @Test public void unsentProofFailureColdExplicitRetryUsesOriginalBodyAndKey()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession current=BuyerJourneyTest.session("a".repeat(64));OfflineMutationQueue queue=new OfflineMutationQueue(m);String id=queue.enqueueUnsentForSession(current,0,"POST",PATH,BuyerTransitionRecoveryTest.body());String original=m.get("offline_mutations");JSONObject row=new JSONArray(original).getJSONObject(0);assertEquals("prepared",OfflineDraftPhase.phase(m,row));assertFalse(m.get(OfflineDraftPhase.KEY).contains(current.account));AtomicInteger posts=new AtomicInteger();
  OfflineMutationQueue.Sender denied=new OfflineMutationQueue.Sender(){public ProductSession session(){return current;}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession expected,long generation){throw new AssertionError("No readback for a known unsent draft");}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession expected,long generation,ApiClient.BeforeDispatch admission)throws Exception{throw new SecurityException("Fresh proof unavailable");}};
  assertEquals(0,queue.flush(denied,current,0));assertEquals(original,m.get("offline_mutations"));assertEquals("prepared",OfflineDraftPhase.phase(m,row));
  OfflineMutationQueue.Sender allowed=new OfflineMutationQueue.Sender(){public ProductSession session(){return current;}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession expected,long generation){throw new AssertionError("No unknown lookup for unsent draft");}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession expected,long generation,ApiClient.BeforeDispatch admission)throws Exception{assertEquals(PATH,path);assertEquals(BuyerTransitionRecoveryTest.body().toString(),body.toString());assertEquals(id,row.getString("id"));assertEquals("prepared",OfflineDraftPhase.phase(m,row));admission.admit();assertEquals("dispatching",OfflineDraftPhase.phase(m,row));posts.incrementAndGet();return BuyerJourneyTest.order().put("Status","cancelled");}};
  assertEquals(1,new OfflineMutationQueue(m).flush(allowed,current,0));assertEquals(1,posts.get());assertEquals(0,queue.size());assertEquals(0,OfflineDraftPhase.records(m).length());
 }
 @Test public void lostResponseAndNotFoundNeverRedispatchOrRotateOriginalDraft()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession current=BuyerJourneyTest.session("a".repeat(64));OfflineMutationQueue queue=new OfflineMutationQueue(m);queue.enqueueUnsentForSession(current,0,"POST",PATH,BuyerTransitionRecoveryTest.body());String original=m.get("offline_mutations");AtomicInteger posts=new AtomicInteger(),reads=new AtomicInteger();OfflineMutationQueue.Sender sender=new OfflineMutationQueue.Sender(){public ProductSession session(){return current;}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession expected,long generation)throws Exception{assertEquals(PATH+"-intent-lookup",path);reads.incrementAndGet();throw new ApiClient.ApiException(409,"original not found","ORIGINAL_NOT_FOUND");}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession expected,long generation,ApiClient.BeforeDispatch admission)throws Exception{admission.admit();posts.incrementAndGet();throw new java.io.IOException("lost response");}};
  assertEquals(0,queue.flush(sender,current,0));JSONObject row=new JSONArray(original).getJSONObject(0);assertEquals("unknown",OfflineDraftPhase.phase(m,row));assertEquals(0,new OfflineMutationQueue(m).flush(sender,current,0));assertEquals(1,posts.get());assertEquals(1,reads.get());assertEquals(original,m.get("offline_mutations"));queue.enqueueUnsentForSession(current,0,"POST",PATH,BuyerTransitionRecoveryTest.body());assertEquals("unknown",OfflineDraftPhase.phase(m,row));assertEquals(original,m.get("offline_mutations"));
 }
 @Test public void legacyMissingPhaseCannotBeReclassifiedAndMalformedMetadataCannotSend()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession current=BuyerJourneyTest.session("a".repeat(64));OfflineMutationQueue queue=new OfflineMutationQueue(m);queue.enqueueForSession(current,0,"POST",PATH,BuyerTransitionRecoveryTest.body());String original=m.get("offline_mutations");queue.enqueueUnsentForSession(current,0,"POST",PATH,BuyerTransitionRecoveryTest.body());assertEquals("unknown",OfflineDraftPhase.phase(m,new JSONArray(original).getJSONObject(0)));assertEquals("",m.get(OfflineDraftPhase.KEY));m.put(OfflineDraftPhase.KEY,"{bad-original-metadata");assertThrows(JSONException.class,()->queue.enqueueUnsentForSession(current,0,"POST",PATH,BuyerTransitionRecoveryTest.body()));assertEquals(original,m.get("offline_mutations"));
 }
 @Test public void accountReplacementAtAdmissionCannotSendOrErasePreparedDraft()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession expected=BuyerJourneyTest.session("a".repeat(64));ProductSession[] current={expected};OfflineMutationQueue queue=new OfflineMutationQueue(m);queue.enqueueUnsentForSession(expected,0,"POST",PATH,BuyerTransitionRecoveryTest.body());String original=m.get("offline_mutations");OfflineMutationQueue.Sender sender=new OfflineMutationQueue.Sender(){public ProductSession session(){return current[0];}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession actor,long generation){throw new AssertionError();}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession actor,long generation,ApiClient.BeforeDispatch admission)throws Exception{current[0]=BuyerJourneyTest.session("b".repeat(64));admission.admit();throw new AssertionError("stale admission cannot send");}};assertEquals(0,queue.flush(sender,expected,0));assertEquals(original,m.get("offline_mutations"));assertEquals("prepared",OfflineDraftPhase.phase(m,new JSONArray(original).getJSONObject(0)));
 }
 @Test public void leavingViewBeforeAdmissionOrAfterResponsePreservesOriginalQueue()throws Exception{
  for(boolean afterResponse:new boolean[]{false,true}){PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession expected=BuyerJourneyTest.session("a".repeat(64));boolean[] view={true};OfflineMutationQueue queue=new OfflineMutationQueue(m);queue.enqueueUnsentForSession(expected,0,"POST",PATH,BuyerTransitionRecoveryTest.body());String original=m.get("offline_mutations");OfflineMutationQueue.Sender sender=new OfflineMutationQueue.Sender(){public boolean current(){return view[0];}public ProductSession session(){return expected;}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession actor,long generation){throw new AssertionError();}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession actor,long generation,ApiClient.BeforeDispatch admission)throws Exception{if(!afterResponse)view[0]=false;admission.admit();if(!afterResponse)throw new AssertionError("Leaving view must reject dispatch");view[0]=false;return BuyerJourneyTest.order().put("Status","cancelled");}};assertEquals(0,queue.flush(sender,expected,0));assertEquals(original,m.get("offline_mutations"));assertEquals(afterResponse?"unknown":"prepared",OfflineDraftPhase.phase(m,new JSONArray(original).getJSONObject(0)));}
 }

 @Test public void leavingViewDuringTrackedUnknownReadbackCannotClearLedger()throws Exception{
  PrivacyLifecycleTest.Memory m=new PrivacyLifecycleTest.Memory();ProductSession expected=BuyerJourneyTest.session("a".repeat(64));PrivacyLifecycle privacy=new PrivacyLifecycle(m);PrivacyLifecycle.Ticket ticket=privacy.admit(expected.account,"POST",PATH,BuyerTransitionRecoveryTest.body());privacy.dispatch(ticket);privacy.outcome(ticket,false);String original=m.get(PrivacyLifecycle.RECORD);boolean[] view={true};OfflineMutationQueue.Sender sender=new OfflineMutationQueue.Sender(){public boolean current(){return view[0];}public ProductSession session(){return expected;}public JSONObject requestForSession(String method,String path,JSONObject body,ProductSession actor,long generation)throws Exception{view[0]=false;return BuyerTransitionRecoveryTest.value(body);}};assertThrows(SecurityException.class,()->BuyerTransitionRecovery.recoverTracked(privacy,sender,expected,0));assertEquals(original,m.get(PrivacyLifecycle.RECORD));
 }

}
